 if(id==='entity-tabs')return `<div class="x-tabs" role="tablist" aria-label="Разделы выезда">${['План','Результат','История'].map((n,i)=>`<button type="button" id="x-entity-tab-${side}-${i}" role="tab" tabindex="${i===0?0:-1}" aria-selected="${i===0}" aria-controls="x-entity-panel-${side}-${i}" data-x-panel-key="${i}" data-x-action="tab" data-x-probe="${i===0?'main':'tab'+i}">${n}</button>`).join('')}</div>${['План','Результат','История'].map((n,i)=>`<section class="x-tab-content" role="tabpanel" id="x-entity-panel-${side}-${i}" aria-labelledby="x-entity-tab-${side}-${i}" data-x-tab-panel="${i}" ${i?'hidden':''}>${i===0?`<p>План: 3 остановки · 2 инженера</p>${field('Заметка к плану','Проверить доступ','text','plan-note')}`:i===1?`<p>Результат ещё не отправлен.</p>${field('Заметка к результату','','text','result-note')}`:'<p>24.10.2026 · Анна: создан выезд № 1042</p>'}</section>`).join('')}${help('Вкладки сохраняют введённое в каждой панели. Переключение не сохраняет выезд и не стирает черновик.')}`;
 if(id==='record-card')return card(`${row(badge('Черновик')+count(3))}<h3>Выезд № 1042</h3><p>Насосная станция · Анна Смирнова</p>${row(button('Открыть выезд','navigate')+button('Другие действия','menu','tertiary','menu'))}`);
