 if(id==='bottom-sheet')return `${map()}<div class="x-sheet-preview" data-x-probe="container"><span class="x-drag-handle" aria-hidden="true"></span><h3>Остановки маршрута</h3><ol><li>Депо · начало</li><li>Насосная станция · 10:20</li></ol>${button('Открыть остановки','sheet')}</div>${help('Явный вход; список доступен без drag. Выход — «Готово» или Escape.')}`;
